{
  "name": "RTO示波器",
  "name_en": "RTO Oscilloscope",
  "manufacturer": "Rohde & Schwarz",
  "description": "Rohde & Schwarz RTO 系列数字示波器，用于实验中的波形采集、触发设置、时基与通道量程调整、单次采样、平均采样以及屏幕截图获取。该接口还暴露了一些通用远程连接、参数读写和数字接口相关方法，可能用于配套测量系统中的扩展控制。",
  "description_en": "A Rohde & Schwarz RTO-series digital oscilloscope used in laboratory experiments for waveform acquisition, trigger setup, timebase and channel scale adjustment, single-shot capture, averaging, and screenshot retrieval. The interface also exposes some generic remote-connection, parameter read/write, and digital-interface methods that may support extended control in a larger measurement setup.",
  "tag_hints": [
    "oscilloscope",
    "waveform acquisition",
    "trigger configuration",
    "timebase control",
    "channel scaling",
    "screen capture",
    "SCPI remote control",
    "Rohde & Schwarz RTO"
  ],
  "actions": [
    {
      "action_name": "auto-idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-set_trigger_mode",
      "description": "设置触发模式。",
      "description_en": "Set the trigger mode."
    },
    {
      "action_name": "auto-set_trigger_level",
      "description": "设置触发电平。",
      "description_en": "Set the trigger level."
    },
    {
      "action_name": "auto-set_trigger_ext",
      "description": "设置外部触发配置。",
      "description_en": "Set the external trigger configuration."
    },
    {
      "action_name": "auto-set_trigger_src",
      "description": "设置触发源。",
      "description_en": "Set the trigger source."
    },
    {
      "action_name": "auto-set_trigger_slope",
      "description": "设置触发沿方向。",
      "description_en": "Set the trigger slope."
    },
    {
      "action_name": "auto-set_trigger_coupling",
      "description": "设置触发耦合方式。",
      "description_en": "Set the trigger coupling."
    },
    {
      "action_name": "auto-set_time_scale",
      "description": "设置时间刻度。",
      "description_en": "Set the time scale."
    },
    {
      "action_name": "auto-set_channel_scale",
      "description": "设置通道量程。",
      "description_en": "Set the channel scale."
    },
    {
      "action_name": "auto-do_single_shot",
      "description": "执行单次采集。",
      "description_en": "Perform a single-shot acquisition."
    },
    {
      "action_name": "auto-set_averaging",
      "description": "设置是否启用平均采样。",
      "description_en": "Set whether averaging is enabled."
    },
    {
      "action_name": "auto-set_format_real",
      "description": "设置实数数据格式。",
      "description_en": "Set the real-valued data format."
    },
    {
      "action_name": "auto-set_average_count",
      "description": "设置平均次数。",
      "description_en": "Set the averaging count."
    },
    {
      "action_name": "auto-sync",
      "description": "同步设备或通信状态。",
      "description_en": "Synchronize the device or communication state."
    },
    {
      "action_name": "auto-do_get_screenshot",
      "description": "获取示波器屏幕截图。",
      "description_en": "Retrieve a screenshot from the oscilloscope."
    },
    {
      "action_name": "auto-get_channel_data",
      "description": "获取通道波形数据。",
      "description_en": "Get channel waveform data."
    },
    {
      "action_name": "auto-is_averaging_complete",
      "description": "查询平均采样是否完成。",
      "description_en": "Check whether averaging is complete."
    },
    {
      "action_name": "auto-set_maximum_rate",
      "description": "设置最大采样或传输速率。",
      "description_en": "Set the maximum sampling or transfer rate."
    },
    {
      "action_name": "auto-connect_server",
      "description": "连接到远程服务器。",
      "description_en": "Connect to a remote server."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新建立连接。",
      "description_en": "Reconnect the session."
    },
    {
      "action_name": "auto-connect_device",
      "description": "连接设备。",
      "description_en": "Connect to the device."
    },
    {
      "action_name": "auto-load_settings",
      "description": "加载设备设置。",
      "description_en": "Load device settings."
    },
    {
