    },
    {
      "action_name": "auto-getd",
      "description": "读取双精度数值参数。",
      "description_en": "Get a double-precision numeric parameter."
    },
    {
      "action_name": "auto-getv",
      "description": "读取向量或数组参数。",
      "description_en": "Get a vector or array parameter."
    },
    {
      "action_name": "auto-find",
      "description": "查找单个节点或资源。",
      "description_en": "Find a single node or resource."
    },
    {
      "action_name": "auto-finds",
      "description": "查找多个节点或资源。",
      "description_en": "Find multiple nodes or resources."
    },
    {
      "action_name": "auto-subs",
      "description": "订阅数据节点或信号。",
      "description_en": "Subscribe to data nodes or signals."
    },
    {
      "action_name": "auto-unsubs",
      "description": "取消订阅数据节点或信号。",
      "description_en": "Unsubscribe from data nodes or signals."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询数据或状态。",
      "description_en": "Poll data or status."
    },
    {
      "action_name": "auto-configure_awg_file",
      "description": "通过文件配置 AWG。",
      "description_en": "Configure the AWG using a file."
    },
    {
      "action_name": "auto-configure_awg_string",
      "description": "通过字符串配置 AWG。",
      "description_en": "Configure the AWG using a string."
    },
    {
      "action_name": "auto-read_scope",
      "description": "读取示波数据。",
      "description_en": "Read scope data."
    },
    {
      "action_name": "auto-restart",
      "description": "重启设备或控制会话。",
      "description_en": "Restart the device or control session."
    },
    {
      "action_name": "auto-on",
      "description": "开启输出或功能。",
      "description_en": "Turn on the output or function."
    },
    {
      "action_name": "auto-off",
      "description": "关闭输出或功能。",
      "description_en": "Turn off the output or function."
    },
    {
      "action_name": "auto-extclk",
      "description": "设置或切换外部时钟。",
      "description_en": "Set or switch the external clock."
    },
    {
      "action_name": "auto-sampleclk",
      "description": "设置采样时钟。",
      "description_en": "Set the sample clock."
    },
    {
      "action_name": "auto-mode",
      "description": "设置工作模式。",
      "description_en": "Set the operating mode."
    },
    {
      "action_name": "auto-direct",
      "description": "设置直接模式或直通路径。",
      "description_en": "Set the direct mode or direct path."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准数字输入输出协议。",
      "description_en": "Calibrate the digital I/O protocol."
    },
    {
      "action_name": "auto-dio_snapshot",
      "description": "获取数字输入输出状态快照。",
      "description_en": "Capture a snapshot of digital I/O states."
    },
    {
      "action_name": "auto-awg_dio_snapshot",
      "description": "获取 AWG 数字输入输出状态快照。",
      "description_en": "Capture a snapshot of AWG digital I/O states."
    },
    {
      "action_name": "auto-dio_testmode",
      "description": "设置数字输入输出测试模式。",
      "description_en": "Set the digital I/O test mode."
    },
    {
      "action_name": "auto-onOffMultiple",
      "description": "批量开启或关闭多个通道或功能。",
      "description_en": "Turn multiple channels or functions on or off in batch."
    }
  ]
}

